    last=None
    for i,ch in enumerate(s):
        if ch not in (' ', '\t'):
            if first is None:
                first=offsets[i]
            last=offsets[i]
    if first is None:
        return "⠀"
    w = last+1
    cols=[1 if p>=first else 0 for p in range(w)]
    # scaling interval method
    n_scaled = math.ceil(w*H)
    filled_scaled=[0]*n_scaled
    for p,filled in enumerate(cols):
        if filled:
            start = int(p*H)
            end = math.ceil((p+1)*H)-1
            for sp in range(start, min(end+1, n_scaled)):
                filled_scaled[sp]=1
    n_cells=math.ceil(n_scaled/2)
    cells=[0]*n_cells
    for sp,filled in enumerate(filled_scaled):
        if filled:
            cell=sp//2
            side=sp%2
            if side==0:
                cells[cell]|=0x01
            else:
                cells[cell]|=0x08
