    filled_scaled=[0]*n_scaled
    for sp in range(n_scaled):
        center = sp+0.5
        for p in range(w):
            if p < first:
                continue
            # check if center in [p*H, (p+1)*H)
            if p*H <= center < (p+1)*H:
                filled_scaled[sp]=1
                break
    n_cells=math.ceil(n_scaled/2)
    cells=[0]*n_cells
    for sp,filled in enumerate(filled_scaled):
        if filled:
            cell=sp//2
            side=sp%2
            if side==0:
                cells[cell]|=0x01
            else:
                cells[cell]|=0x08
    return "".join(chr(0x2800|b) for b in cells) if cells else ""

