fn main() {
    let mut cmd = build_cli();
    let matches = match cmd.try_get_matches_from_mut(std::env::args()) {
        Ok(m) => m,
        Err(e) => {
            let code = e.exit_code();
            if code == 0 {
                // help/version printed
                e.exit();
            } else {
                e.exit();
            }
        }
    };

    if matches.get_flag("version") {
        println!("code-minimap 0.6.8");
        return;
    }

    if let Some((name, sub_m)) = matches.subcommand() {
        if name == "completion" {
            let shell_str = sub_m.get_one::<String>("shell").unwrap().as_str();
            let shell = match shell_str {
                "bash" => Shell::Bash,
                "fish" => Shell::Fish,
                "zsh" => Shell::Zsh,
                "powershell" => Shell::PowerShell,
                "elvish" => Shell::Elvish,
                _ => unreachable!(),
            };
            let mut c = build_cli();
            generate(shell, &mut c, "code-minimap", &mut std::io::stdout());
            return;
        }
    }

    let hscale: f64 = *matches.get_one::<f64>("horizontal-scale").unwrap();
    let vscale: f64 = *matches.get_one::<f64>("vertical-scale").unwrap();
    let padding: Option<usize> = matches.get_one::<usize>("padding").copied();
    let encoding_str: &String = matches.get_one::<String>("encoding").unwrap();
    let encoding = encoding_str.as_str();
    let file: Option<&String> = matches.get_one::<String>("file");

    let content_bytes: Vec<u8> = if let Some(path_str) = file {
        let path = PathBuf::from(path_str);
        match std::fs::read(&path) {
            Ok(b) => b,
            Err(e) => {
                eprintln!("code-minimap: {} (os error {})", e, e.raw_os_error().unwrap_or(2));
                std::process::exit(1);
            }
        }
    } else {
        let mut buf = Vec::new();
        std::io::stdin().read_to_end(&mut buf).unwrap();
        buf
    };

    let text: String = match encoding {
        "utf8-lossy" => String::from_utf8_lossy(&content_bytes).into_owned(),
        "utf8" => match String::from_utf8(content_bytes) {
            Ok(s) => s,
            Err(_) => {
                eprintln!("code-minimap: stream did not contain valid UTF-8");
                std::process::exit(1);
            }
        },
        _ => unreachable!(),
    };

    let lines: Vec<String> = if text.is_empty() {
        Vec::new()
    } else {
        text.lines().map(|s| s.to_string()).collect()
    };

    let output = render(&lines, hscale, vscale, padding);
    let stdout = std::io::stdout();
    let mut out = stdout.lock();
    out.write_all(output.as_bytes()).unwrap();
}

fn render(lines: &[String], hscale: f64, vscale: f64, padding: Option<usize>) -> String {
    if lines.is_empty() {
        return String::new();
    }
    let h = hscale;
    let v = vscale;

    struct LineInfo {
        w: usize,
        first: Option<usize>,
    }
    let mut infos = Vec::new();
    let mut max_scaled_w = 0usize;
    for line in lines {
        let b_lens: Vec<usize> = line.chars().map(|c| c.len_utf8()).collect();
        let mut offs = Vec::new();
        let mut off = 0usize;
        for &bl in &b_lens {
            offs.push(off);
            off += bl;
        }
        let mut first: Option<usize> = None;
        let mut last: Option<usize> = None;
        for (i, ch) in line.chars().enumerate() {
            if ch != ' ' && ch != '\t' {
                if first.is_none() {
                    first = Some(offs[i]);
                }
                last = Some(offs[i]);
            }
        }
        let w = if let Some(l) = last {
            l + 1
        } else {
            1
        };
        let scaled_w = (w as f64 * h).floor() as usize;
        if scaled_w > max_scaled_w {
            max_scaled_w = scaled_w;
        }
        infos.push(LineInfo { w, first });
    }

    let orig_h = lines.len();
    let scaled_h = (orig_h as f64 * v).ceil() as usize;

    if scaled_h == 0 || max_scaled_w == 0 {
        return String::new();
    }

    let braille_w = (max_scaled_w + 1) / 2;
    let braille_h = (scaled_h + 3) / 4;

    let mut grid = vec![vec![0u8; max_scaled_w]; scaled_h];

    for (y, info) in infos.iter().enumerate() {
        let first = match info.first {
            Some(f) => f,
            None => continue,
        };
        let w = info.w;
        let y0 = y as f64 * v;
        let y1 = (y + 1) as f64 * v;
        for sr in 0..scaled_h {
            let sr0 = sr as f64;
            let sr1 = sr as f64 + 1.0;
            if sr0 >= y1 || sr1 <= y0 {
                continue;
            }
            let x0 = first as f64 * h;
            let x1 = w as f64 * h;
            for sp in 0..max_scaled_w {
                let sp0 = sp as f64;
                let sp1 = sp as f64 + 1.0;
                if sp0 >= x1 || sp1 <= x0 {
                    continue;
                }
                grid[sr][sp] = 1;
            }
        }
    }

    let mut braille_cells = vec![vec![0u32; braille_w]; braille_h];
    for sr in 0..scaled_h {
        for sp in 0..max_scaled_w {
            if grid[sr][sp] == 0 {
                continue;
            }
            let bx = sp / 2;
            let by = sr / 4;
            let dx = sp % 2;
            let dy = sr % 4;
            let bit = match (dx, dy) {
                (0, 0) => 0x01,
                (0, 1) => 0x02,
                (0, 2) => 0x04,
                (0, 3) => 0x40,
                (1, 0) => 0x08,
                (1, 1) => 0x10,
                (1, 2) => 0x20,
                (1, 3) => 0x80,
                _ => 0,
            };
            braille_cells[by][bx] |= bit;
        }
    }

    let mut result = String::new();
    for by in 0..braille_h {
        let mut line = String::new();
        for bx in 0..braille_w {
            line.push(std::char::from_u32(0x2800 + braille_cells[by][bx]).unwrap());
        }
        if let Some(pad) = padding {
            while line.ends_with('\u{2800}') {
                line.pop();
            }
            if line.is_empty() {
                if braille_w > 0 {
                    line = "\u{2800}".to_string();
                }
            }
            let len = line.chars().count();
            if len < pad {
                line.push_str(&" ".repeat(pad - len));
            }
            result.push_str(&line);
            result.push('\n');
        } else {
            while line.ends_with('\u{2800}') {
                line.pop();
            }
            if line.is_empty() {
                continue;
            }
            result.push_str(&line);
            result.push('\n');
        }
    }
    if result.is_empty() && braille_h > 0 && max_scaled_w > 0 {
        let has_content = infos.iter().any(|i| i.first.is_some());
        if !has_content {
            if let Some(pad) = padding {
                let mut line = "⠀".to_string();
                if line.chars().count() < pad {
                    line.push_str(&" ".repeat(pad - 1));
                }
                result.push_str(&line);
                result.push('\n');
            } else {
                result.push_str("⠀\n");
            }
        }
    }
    result
}
